const STALE_MS = 2 * 60 * 1000;
const currentId = String($execution.id);
const now = Date.now();

function rowsFrom(nodeName) {
  try {
    const raw = $(nodeName).first().json;
    if (!raw) return [];
    if (Array.isArray(raw.data)) return raw.data;
    if (Array.isArray(raw)) return raw;
    if (raw.id) return [raw];
    return [];
  } catch (e) {
    return [];
  }
}

const rows = []
  .concat(rowsFrom('List running'))
  .concat(rowsFrom('List waiting'))
  .concat(rowsFrom('List new'));

const seen = {};
const stale = [];
for (const row of rows) {
  const eid = String(row.id || '');
  if (!eid || eid === currentId || seen[eid]) continue;
  seen[eid] = true;
  const st = String(row.status || '');
  if (['running', 'waiting', 'new'].indexOf(st) === -1) continue;
  const started = Date.parse(row.startedAt || '');
  if (Number.isFinite(started) && (now - started) < STALE_MS) continue;
  // missing startedAt (queued `new`) counts as stale, except the current run
  stale.push({
    json: {
      executionId: eid,
      startedAt: row.startedAt || '',
      status: st,
    },
  });
}

if (!stale.length) {
  return [{ json: { executionId: null } }];
}
return stale;

const stopped = items
  .map((item) => item.json && item.json.executionId)
  .filter(Boolean);
return [{ json: { stale_stopped: stopped } }];

const OPS_CHAT_ID = '410199989';
const THRESHOLD_USD = 1;
const USD_RUB_RATE = 80;
const DAILY_TIME = '09:00';

function triggerSource() {
  try { $('Telegram Trigger').first(); return 'telegram'; } catch (e) {}
  try { $('Daily 09:00 MSK').first(); return 'schedule'; } catch (e) {}
  try { $('Manual Trigger').first(); return 'manual'; } catch (e) {}
  return 'unknown';
}

const base = {
  threshold_usd: THRESHOLD_USD,
  usd_rub_rate: USD_RUB_RATE,
  notify_time: DAILY_TIME,
};

const source = triggerSource();

if (source === 'telegram') {
  const tg = $('Telegram Trigger').first().json || {};
  const msg = tg.message || tg;
  const textRaw = msg.text != null ? String(msg.text) : '';
  if (!textRaw) return [];
  const parts = textRaw.trim().split(/\s+/);
  const cmd = parts[0].split('@')[0].toLowerCase();
  const chatId = String((msg.chat && msg.chat.id) || (tg.chat && tg.chat.id) || '');
  if (!chatId) return [];

  if (cmd === '/time') {
    return [{
      json: {
        ...base,
        mode: 'time_reply',
        source: 'command',
        telegram_chat_id: chatId,
        message_text: [
          `⏰ Daily report: ${DAILY_TIME} MSK`,
          '',
          'Time is fixed. Use /balance for a report now.',
        ].join('\n'),
      },
    }];
  }

  if (cmd !== '/balance' && cmd !== '/start') return [];
  return [{
    json: {
      ...base,
      mode: 'balances',
      source: 'command',
      telegram_chat_id: chatId,
    },
  }];
}

if (!OPS_CHAT_ID) return [];

return [{
  json: {
    ...base,
    mode: 'balances',
    source: source === 'schedule' ? 'schedule' : 'manual',
    telegram_chat_id: String(OPS_CHAT_ID),
  },
}];

const prep = $('Prepare').first().json;
const deepseek = $('HTTP DeepSeek').first().json;
const polza = $('HTTP Polza').first().json;
const thrUsd = Number(prep.threshold_usd);
const rate = Number(prep.usd_rub_rate);
const thresholdUsd = Number.isFinite(thrUsd) ? thrUsd : 1;
const usdRubRate = Number.isFinite(rate) && rate > 0 ? rate : 80;

function money(amount, currency) {
  const n = Number(amount);
  if (!Number.isFinite(n)) return '?';
  const cur = String(currency || '').toUpperCase();
  if (cur === 'USD') return `$${n.toFixed(2)}`;
  if (cur === 'RUB') return `${n.toFixed(2)} ₽`;
  return `${n.toFixed(2)} ${currency}`;
}

function thrFor(currency) {
  return String(currency).toUpperCase() === 'RUB' ? thresholdUsd * usdRubRate : thresholdUsd;
}

function parseDeepseek(raw) {
  if (!raw || raw.error) return { ok: false, error: (raw && (raw.error || raw.message)) || 'unavailable' };
  const infos = raw.balance_infos || [];
  const chosen = infos.find((i) => String(i.currency || '').toUpperCase() === 'USD') || infos[0];
  if (!chosen) return { ok: false, error: 'no_balance_infos' };
  const amount = Number(chosen.total_balance);
  if (!Number.isFinite(amount)) return { ok: false, error: 'bad_amount' };
  return { ok: true, amount, currency: chosen.currency || 'USD' };
}

function parsePolza(raw) {
  if (!raw || raw.error) return { ok: false, error: (raw && (raw.error || raw.message)) || 'unavailable' };
  const amount = Number(raw.amount);
  if (!Number.isFinite(amount)) return { ok: false, error: 'bad_amount' };
  return { ok: true, amount, currency: 'RUB' };
}

const ds = parseDeepseek(deepseek);
const pz = parsePolza(polza);

const now = new Date();
const parts = new Intl.DateTimeFormat('en-CA', {
  timeZone: 'Europe/Moscow',
  year: 'numeric', month: '2-digit', day: '2-digit',
  hour: '2-digit', minute: '2-digit', hour12: false,
}).formatToParts(now);
const get = (t) => (parts.find((p) => p.type === t) || {}).value;
const stamp = `${get('year')}-${get('month')}-${get('day')} ${get('hour')}:${get('minute')}`;

const agents = [
  { name: 'DeepSeek', ...ds },
  { name: 'Polza (Judge)', ...pz },
];

const lines = [`💰 Balances · ${stamp} MSK`, ''];
const low = [];
for (const a of agents) {
  if (!a.ok) {
    lines.push(`• ${a.name}: ⚠️ error (${a.error || 'unavailable'})`);
    continue;
  }
  const thr = thrFor(a.currency);
  const warn = a.amount < thr ? ' ⚠️' : '';
  if (a.amount < thr) low.push(a.name);
  lines.push(`• ${a.name}: ${money(a.amount, a.currency)}${warn}`);
}
lines.push('');
const usdLabel = Number.isInteger(thresholdUsd) ? String(thresholdUsd) : thresholdUsd.toFixed(2);
const rubThr = thrFor('RUB');
const rubLabel = Number.isInteger(rubThr) ? String(rubThr) : String(Math.round(rubThr));
lines.push(`⚠️ Below $${usdLabel} / ${rubLabel} ₽: ${low.length ? low.join(', ') : '— none —'}`);

return [{
  json: {
    telegram_chat_id: prep.telegram_chat_id,
    message_text: lines.join('\n'),
    source: prep.source,
    mode: 'balances',
  },
}];
